const blankLead = () => Object.fromEntries(LEAD_FIELDS.map((f) => [f, '']));
const mergeLead = (existing, updates) => {
  const out = blankLead();
  for (const f of LEAD_FIELDS) { if (existing && existing[f] !== undefined && existing[f] !== null) out[f] = String(existing[f]); }
