const leadIdFor = (phone, email) => digits(phone) ? 'P' + digits(phone) : (norm(email) ? 'E' + norm(email).toLowerCase() : '');
const tplLang = norm($env.WA_TEMPLATE_LANG) || 'en';
const waClean = (s) => norm(s).replace(/[\r\n\t]+/g, ' ').replace(/ {5,}/g, '    ').slice(0, 900) || '-';
// Business-initiated WhatsApp messages MUST be approved templates. Never free-form text.
const buildTemplate = (key, phone, params) => {
  const name = norm($env['WA_TPL_' + key]);
  if (!name) return { ok: false, reason: 'template_not_configured:WA_TPL_' + key };
  const to = digits(phone);
  if (to.length < 8 || to.length > 15) return { ok: false, reason: 'invalid_phone' };
  return {
    ok: true,
    template: name,
    payload: {
      messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'template',
      template: { name, language: { code: tplLang }, components: [{ type: 'body', parameters: params.map((p) => ({ type: 'text', text: waClean(p) })) }] },
    },
  };
};
// Returns '' when the lead may be contacted, otherwise the reason it must NOT be.
const notContactableReason = (l) => {
  if (!yes(l.opt_in)) return 'no_opt_in';
  if (norm(l.opt_out_at)) return 'opted_out';
  const st = norm(l.status).toLowerCase();
  if (['unsubscribed', 'converted', 'churned'].includes(st)) return 'status_' + st;
  const d = digits(l.phone);
  if (d.length < 8 || d.length > 15) return 'invalid_phone';
  return '';
};
const inc = $('Validate Lead').first().json.incoming;
const existing = $input.first().json || {};
const isDup = norm(existing.lead_id) !== '';
const now = nowIso();
const wasOptedOut = norm(existing.opt_out_at) !== '' || norm(existing.status).toLowerCase() === 'unsubscribed';
const u = {
  lead_id: inc.lead_id, phone: inc.phone || existing.phone, email: inc.email || existing.email, name: existing.name || inc.name,
  user_type: inc.user_type !== 'unknown' ? inc.user_type : (existing.user_type || 'unknown'),
  source: existing.source || inc.source, intent_level: inc.intent_level || existing.intent_level, country: inc.country || existing.country,
  signup_date: existing.signup_date || now.slice(0, 10), first_contact: existing.first_contact || now,
  status: existing.status || 'new', wa_day: existing.wa_day || '0',
};
if (inc.consent) {
  // A fresh, explicit consent (form checkbox) opts the lead in - also re-subscribes a previously unsubscribed lead.
  u.opt_in = 'yes'; u.opt_in_at = now; u.opt_in_source = 'web_form'; u.opt_out_at = '';
  if (wasOptedOut) u.status = 'new';
} else if (!norm(existing.opt_in)) { u.opt_in = 'no'; }
const lead = mergeLead(existing, u);
let waReason = '';
let payload = null;
if (!inc.consent) waReason = 'no_consent';
else if (!lead.phone) waReason = 'no_phone';
else if ((parseInt(lead.wa_day, 10) || 0) > 0) waReason = 'welcome_already_sent';
else {
  const why = notContactableReason(lead);
  if (why) waReason = why;
  else {
    const t = buildTemplate('WELCOME_D1', lead.phone, [lead.name || 'there', appLink() || 'our app']);
    if (!t.ok) waReason = t.reason; else payload = t.payload;
  }
}
return [{ json: { lead, is_duplicate: isDup, send_welcome: !!payload, welcome_reason: waReason, payload } }];

const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
