const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const src = $('Merge Lead').itemMatching(i).json;
  const ok = !!(r.messages && r.messages[0] && r.messages[0].id) && !r.error;
  const lead = { ...src.lead };
